library(shiny)

# ---- small helpers ----------------------------------------------------------

# manual bootstrap CI for a Pearson correlation
boot_r_ci &lt;- function(x, y, reps = 600) {
  n &lt;- length(x)
  bs &lt;- numeric(reps)
  for (i in seq_len(reps)) {
    idx &lt;- sample.int(n, n, replace = TRUE)
    bs[i] &lt;- suppressWarnings(cor(x[idx], y[idx]))
  }
  quantile(bs, c(.025, .975), na.rm = TRUE)
}

