           ylab = "Predation risk",
           main = "Relationship between movement speed and predation risk",
           cex.main = 1.2, cex.lab = 1.15, cex.axis = 1.1, bty = "l")
      abline(lm(d$Y ~ d$X), col = "black", lty = 2, lwd = 2)
    }
    legend("topleft", bty = "n", cex = 1.2,
           legend = paste0("r = ", round(r, 2)))
  })

  output$t10_verdict &lt;- renderUI({
    d &lt;- t10_data()
    r_raw &lt;- cor(d$X, d$Y)
    rx &lt;- resid(lm(d$X ~ d$Z)); ry &lt;- resid(lm(d$Y ~ d$Z))
    r_adj &lt;- cor(rx, ry)
    if (input$t10_ctrl) {
      HTML(paste0("Once we account for body mass, the ",
                  "correlation drops to r = &lt;b&gt;", round(r_adj, 2), "&lt;/b&gt; - essentially ",
                  "nothing. The apparent link was never about movement speed; it was body mass ",
