# ---- small helpers ----------------------------------------------------------
# mean and 95% CI half-width for a vector
mean_ci &lt;- function(x) {
  n  &lt;- length(x)
  m  &lt;- mean(x)
  se &lt;- sd(x) / sqrt(n)
  ci &lt;- se * qt(0.975, n - 1)
  list(m = m, lo = m - ci, hi = m + ci)
}

